classdef TestScheduleRuleCompat < matlab.unittest.TestCase
% Source-level regression tests for recurring schedule rules
% (BrainCOGS/tech_calendar_streamlit#125, BrainCOGS/U19-pipeline-matlab#60).
%
% scheduler.Schedule rows with a rule_id are generated by U19-pipeline-python's
% materialize_schedule. The nightly copy-forward must leave them alone: copying a
% weekday-only rule row onto Saturday schedules a mouse that should rest, and
% inserting into a slot the generator already filled fails and pages the devs.
% Like TestScheduledTaskScripts these read the files as text and need no database.

    properties(Constant)
        PopulateScript = fullfile('scripts', 'populate_schedule_for_tomorrow.m');
    end

    methods(Static)
        function txt = read_text(relative_path)
            root = fileparts(fileparts(mfilename('fullpath')));
            txt = strrep(fileread(fullfile(root, relative_path)), sprintf('\r\n'), newline);
        end

        function body = function_body(txt, name)
            % Text of a local function from its "function ... name(" line to the next "function".
            starts = regexp(txt, ['(?m)^function[^\n]*\<' name '\s*\('], 'once');
            assert(~isempty(starts), 'function %s not found', name);
            rest = txt(starts + 1:end);
            next = regexp(rest, '(?m)^function\s', 'once');
            if isempty(next)
                body = txt(starts:end);
            else
                body = txt(starts:starts + next - 1);
            end
        end

        function code = strip_comments(txt)
            % Whole-line comments only: a trailing-comment regex would also cut
            % sprintf('date="%s"', ...) format strings.
            code = regexprep(txt, '(?m)^\s*%[^\n]*$', '');
        end
    end

    methods(Test)

        function testLegacyConditionExcludesRuleRows(testCase)
            txt = TestScheduleRuleCompat.read_text(TestScheduleRuleCompat.PopulateScript);
            body = TestScheduleRuleCompat.function_body(txt, 'legacy_schedule_condition');
            testCase.verifyNotEmpty(regexp(body, 'rule_id IS NULL', 'once'));
            testCase.verifyNotEmpty(regexp(body, 'subject_fullname IS NOT NULL', 'once'));
        end

        function testEverySourceFetchUsesLegacyCondition(testCase)
        % Each fetch that produces rows to copy (one_date / candidate_entries) must be
        % restricted by legacy_cond.
            main = TestScheduleRuleCompat.strip_comments( ...
                TestScheduleRuleCompat.function_body( ...
                    TestScheduleRuleCompat.read_text(TestScheduleRuleCompat.PopulateScript), ...
                    'populate_schedule_for_tomorrow'));
            lines = strsplit(main, newline);
            source_fetches = lines(~cellfun(@isempty, ...
                regexp(lines, '(one_date|candidate_entries)\s*=\s*fetch\(scheduler\.Schedule', 'once')));
            testCase.verifyGreaterThanOrEqual(numel(source_fetches), 3);
            for i = 1:numel(source_fetches)
                testCase.verifyNotEmpty(regexp(source_fetches{i}, 'legacy_cond', 'once'), ...
                    sprintf('copy source not restricted to legacy rows: %s', strtrim(source_fetches{i})));
            end
        end

        function testRuleOnlyDayDoesNotTriggerLookBack(testCase)
        % If today is all rule rows, the legacy fetch is empty; that must not be
        % mistaken for an empty day and re-populate from older dates.
            main = TestScheduleRuleCompat.strip_comments( ...
                TestScheduleRuleCompat.function_body( ...
                    TestScheduleRuleCompat.read_text(TestScheduleRuleCompat.PopulateScript), ...
                    'populate_schedule_for_tomorrow'));
            guard = regexp(main, 'isempty\(one_date\)\s*&&\s*count\(scheduler\.Schedule', 'once');
            look_back = regexp(main, 'for\s+k\s*=\s*1\s*:\s*5', 'once');
            testCase.verifyNotEmpty(guard, 'missing the all-rule-rows guard');
            testCase.verifyNotEmpty(look_back);
            testCase.verifyLessThan(guard, look_back, 'the guard must run before the look-back loop');
        end

        function testRuleIdStrippedBeforeEveryRedate(testCase)
            main = TestScheduleRuleCompat.strip_comments( ...
                TestScheduleRuleCompat.function_body( ...
                    TestScheduleRuleCompat.read_text(TestScheduleRuleCompat.PopulateScript), ...
                    'populate_schedule_for_tomorrow'));
            for var = {'candidate_entries', 'one_date'}
                strip = regexp(main, [var{1} '\s*=\s*strip_rule_id\(' var{1} '\)'], 'once');
                redate = regexp(main, ['\[' var{1} '\(:\)\.date\]\s*=\s*deal'], 'once');
                testCase.verifyNotEmpty(strip, sprintf('%s is never stripped of rule_id', var{1}));
                testCase.verifyLessThan(strip, redate, ...
                    sprintf('%s is re-dated before rule_id is stripped', var{1}));
            end
        end

        function testOccupiedSlotsDroppedBeforeInsert(testCase)
            main = TestScheduleRuleCompat.strip_comments( ...
                TestScheduleRuleCompat.function_body( ...
                    TestScheduleRuleCompat.read_text(TestScheduleRuleCompat.PopulateScript), ...
                    'populate_schedule_for_tomorrow'));
            inserts = regexp(main, 'attempt_insert_schedule\((\w+)\)', 'start');
            names = regexp(main, 'attempt_insert_schedule\((\w+)\)', 'tokens');
            testCase.verifyNumElements(inserts, 2);
            for i = 1:numel(inserts)
                before = main(1:inserts(i));
                testCase.verifyNotEmpty( ...
                    regexp(before, [names{i}{1} '\s*=\s*drop_occupied_slots\(' names{i}{1}], 'once'), ...
                    sprintf('%s is inserted without dropping occupied slots', names{i}{1}));
            end
        end

        function testColumnDetectionFallsBackToDatabase(testCase)
            body = TestScheduleRuleCompat.function_body( ...
                TestScheduleRuleCompat.read_text(TestScheduleRuleCompat.PopulateScript), ...
                'schedule_has_rule_id');
            testCase.verifyNotEmpty(regexp(body, 'information_schema\.columns', 'once'), ...
                'schedule_has_rule_id must not silently assume the column is missing');
        end

        function testScheduleDeclaresNullableRuleId(testCase)
            txt = TestScheduleRuleCompat.read_text(fullfile('schemas', '+scheduler', 'Schedule.m'));
            secondary = txt(strfind(txt, '---'):end);
            testCase.verifyNotEmpty(regexp(secondary, '->\s*\[nullable\]\s*scheduler\.ScheduleRule', 'once'));
        end

        function testRuleTablesExist(testCase)
            for name = {'ScheduleRule', 'ScheduleRuleDay', 'ScheduleRuleException', 'LabClosure'}
                txt = TestScheduleRuleCompat.read_text(fullfile('schemas', '+scheduler', [name{1} '.m']));
                testCase.verifyNotEmpty(regexp(txt, ['classdef\s+' name{1} '\s*<'], 'once'));
            end
            day = TestScheduleRuleCompat.read_text(fullfile('schemas', '+scheduler', 'ScheduleRuleDay.m'));
            testCase.verifyNotEmpty(regexp(day, 'master\s*=\s*scheduler\.ScheduleRule', 'once'));
            testCase.verifyNotEmpty(regexp(day, ...
                'enum\(''Mon'',''Tue'',''Wed'',''Thu'',''Fri'',''Sat'',''Sun''\)', 'once'), ...
                'weekday enum must match the Python definition, in order');
        end

        function testTestScheduleCopiesDropRuleId(testCase)
            txt = TestScheduleRuleCompat.read_text( ...
                fullfile('utils', 'copy_sessions_test_users', 'insert_test_schedule.m'));
            remove = regexp(txt, 'removevars\(schedule_today_abv,\s*''rule_id''\)', 'once');
            first_insert = regexp(txt, 'insert\(scheduler\.Schedule', 'once');
            testCase.verifyNotEmpty(remove);
            testCase.verifyLessThan(remove, first_insert);
        end

    end
end
